"""Taller guiado de cada sesión del curso «Herramientas digitales para la Pastoral».

Se agrega al final de cada sesión (malla.py). Para cada sesión: paso a paso en Google y en Microsoft 365,
un ejemplo listo para copiar, atajos de teclado, problemas frecuentes y un desafío.
"""

NOTA_ATAJOS = ("*Los atajos son para Windows; en Mac, usa Cmd en vez de Ctrl. En Word, Excel y PowerPoint en español "
               "algunos atajos cambian según el idioma del teclado y del programa: si uno no funciona, búscalo pasando el mouse sobre el botón.*")


def taller(google, microsoft, ejemplo, atajos, problemas, desafio):
    p = ["### Taller guiado (en el computador)",
         "Abre el programa y sigue los pasos. Puedes hacerlo en el que use tu comunidad o, mejor aún, en los dos para comparar."]
    p.append("#### Paso a paso en Google\n\n" + "\n".join(f"{i}. {x}" for i, x in enumerate(google, 1)))
    p.append("#### Paso a paso en Microsoft 365\n\n" + "\n".join(f"{i}. {x}" for i, x in enumerate(microsoft, 1)))
    p.append(f"#### {ejemplo[0]}\n\n{ejemplo[1]}")
    if atajos:
        p.append("#### Atajos útiles\n\n" + "| Acción | Atajo |\n|---|---|\n" + "\n".join(f"| {a} | {b} |" for a, b in atajos) + "\n\n" + NOTA_ATAJOS)
    p.append("#### Problemas frecuentes\n\n" + "\n".join(f"- **{a}** {b}" for a, b in problemas))
    p.append(f"#### Desafío\n\n{desafio}")
    return "\n\n".join(p)


